"""Report nominal-only adaptation calibration and its non-adaptive selected setting."""
import json,hashlib,sys,time
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from zj_wam.io import resolve,sha256,write_json
BASE=resolve('artifacts/followup_v1');OUT=BASE/'cube_adaptation_calibration';read=lambda p:json.loads(p.read_text())
def main():
    a=read(OUT/'raw_audit.json');r=read(OUT/'analysis.json');settings=read(OUT/'settings.json');protocol=read(OUT/'protocol.json');sm=read(BASE/'cube_adaptation_smoke/raw_audit.json');assert a['trials']==a['independent_choice_checks']==1620 and a['states']==90 and sm['actual_selector_calls']==48;assert a['analysis_sha256']==sha256(OUT/'analysis.json') and a['settings_sha256']==sha256(OUT/'settings.json')
    for p,h in protocol['inputs'].items():assert sha256(resolve(p))==h,p
    by={x['variant']:x for x in r['summary']};valid=[(x,by[f'constant_r{x:g}']) for x in protocol['config']['constant_radius_grid'] if by[f'constant_r{x:g}']['valid']];expected=sorted(valid,key=lambda pair:(-pair[1]['joint'],-pair[1]['jerk_gain'],pair[0]))[0][0] if valid else None;assert expected==settings['constant_radius'];write_json(OUT/'constant_radius_audit.json',{'independent_sorted_radius':expected,'settings_sha256':sha256(OUT/'settings.json'),'analysis_sha256':sha256(OUT/'analysis.json'),'source_sha256':sha256(Path(__file__))});alpha=settings['alpha'];radius=settings['constant_radius'];pct=lambda x:'미정의' if x is None else f'{100*x:.2f}%'
    lines=['<!-- BEGIN CUBE ADAPTATION CALIBRATION -->','## Cube allowance·계산량 적응의 nominal 보정','', '접촉 기준을 사용하는 같은 다항식 문제에서 고정/allowance만/계산량만/둘 다의 네 조건과 고정 반경 축소·optimizer 후보만 사용하는 대조군을 구현했다. 실제 두 단계 생성기는 기존8개 calibration/development 상태에서48회 실행했고, full bank를 사용하는40회는 원래 후보 행동·계수·예상 jerk·반응·점수와 정확히 일치했다. 나머지8회는 동일 optimizer 후보의 부분집합이었다.','', 'Allowance의 오차 proxy는 과거250개 물리 구간 중 앞125개로 robot PD를 피팅하고 뒤125개의 실제 전달 목표에 대한 robot 반응을 예측해 계산했다. 물체 상태·물성 변경값·미래 물리 결과는 입력하지 않는다. 이것은 robot 예측 오차 proxy이며 물체 보존 확률이나 안전 보증이 아니다.','',f"새24개 nominal calibration family의90개 상태에서18개 설정, 총1,620개 선택을 비교했다. 같은 contact 승인 threshold를 유지하고, 경험적 선택 후 위반율10% 이하·수정 적용25% 이상을 충족하는 설정 중 U와 평균 실제 jerk 감소를 순서대로 최대화했다. Allowance/both가 공유하는 계수는 **α={alpha}**, 고정 축소 대조군의 반경은 **{radius}**가 선택됐다.",'', '현재 선택은 허용량을 줄이지 않는 설정이다. 이를 적응의 성공으로 부르지 않는다. 모든 파라미터 비교는 nominal calibration에서만 수행했으며, 실제 선택 결과는 기존에 감사한 동일 후보의 물리 결과를 재사용했다. 1,620개 선택·조기 종료 조건과 계수 선택을 독립 필터/정렬로 대조했고, 고정 반경 선택도 별도 순위로 확인했다.','', '| Nominal calibration 조건 | U | 수정 적용 | 선택 후 위반율 | 조기 종료 비율 |','| --- | --- | --- | --- | --- |']
    for name in ['fixed','compute',f'allowance_a{alpha:g}',f'both_a{alpha:g}',f'constant_r{radius:g}','cheap_only']:
        x=by[name];lines.append(f"| {name} | {pct(x['joint'])} | {pct(x['active_fraction'])} | {pct(x['risk'])} | {pct(x['early_stop_fraction'])} |")
    lines+=['','위 표는 calibration 재대입 결과다. 조기 종료는 승인된 optimizer 후보가 예상 jerk10% 감소와 해당 단계 최선 예상 감소의90%를 함께 충족할 때만 허용한다. 이 조건이 발생하지 않으면 compute/both도 전체 후보를 계산한다. 실제 계산 시간은 offline calibration 시간으로 대신하지 않고, 별도의 실제 selector 실행에서 단계별 시간·solver 호출·점수 계산 수를 기록한다.','', '전체 nominal/development와 조건 변화에서 고정한 규칙의 실제 실행·독립 감사가 남아 있다. 동일 평균 비용의 고정 대조 및 반복 정책·지연 실행을 포함한 결론도 이 calibration만으로 내리지 않는다.','', '근거: [적응 규칙](../configs/followup_cube_adaptation_factorial.json), [기존 후보 재현 감사](../artifacts/followup_v1/cube_adaptation_smoke/raw_audit.json), [nominal 보정 분석](../artifacts/followup_v1/cube_adaptation_calibration/analysis.json), [고정 설정](../artifacts/followup_v1/cube_adaptation_calibration/settings.json), [보정 선택 감사](../artifacts/followup_v1/cube_adaptation_calibration/raw_audit.json).','<!-- END CUBE ADAPTATION CALIBRATION -->'];section='\n'.join(lines);doc=resolve('docs/ZJ_WAM_FOLLOWUP_RESULTS.md');text=doc.read_text()
    if lines[0] in text:i=text.index(lines[0]);j=text.index(lines[-1])+len(lines[-1]);text=text[:i]+section+text[j:]
    else:i=text.index('<!-- BEGIN CUBE SHIFT CAUSAL COMMANDS -->');text=text[:i]+section+'\n\n'+text[i:]
    doc.write_text(text);write_json(OUT/'report_evidence.json',{'inputs':{p:sha256(OUT/p) for p in ['protocol.json','analysis.json','settings.json','raw_audit.json','constant_radius_audit.json']},'section_sha256':hashlib.sha256(section.encode()).hexdigest(),'source_sha256':sha256(Path(__file__)),'unix':time.time()})
if __name__=='__main__':main()
